-- Jogabilidade: viagem rápida (2 diamantes) com pagamento só na execução, caçada do continente exige estar na área,
-- monstros do mapa aberto (entidades reais: posição, vida, respawn, combate e drops no servidor), chefes com habilidades
-- e padrões de ataque (dados na tabela bosses, combate resolvido no servidor) e cotação de venda (mesma fórmula do shop_sell).
-- Só acrescenta; nada de jogador é apagado.

