create table if not exists world_spawns(id text primary key, creature_id text not null references creatures(id), x int not null, y int not null, rare boolean not null default false);
create index if not exists world_spawns_xy on world_spawns(x, y);
create table if not exists spawn_state(spawn_id text primary key references world_spawns(id), dead_until timestamptz, kills bigint not null default 0);
create index if not exists spawn_state_dead on spawn_state(dead_until);
alter table world_spawns enable row level security; alter table spawn_state enable row level security;
drop policy if exists world_spawns_read on world_spawns; create policy world_spawns_read on world_spawns for select using (true);
drop policy if exists spawn_state_read on spawn_state; create policy spawn_state_read on spawn_state for select using (true);
