create table if not exists bosses(id text primary key, name text not null, city text, x int not null, y int not null, level int not null, hp int not null, atk int not null, def int not null, exp bigint not null,
  sprite text, tint text, abilities jsonb not null default '[]', rewards jsonb not null default '{}', cooldown_h numeric not null default 6, retry_min numeric not null default 10, min_level int not null default 1, enabled boolean not null default true);
create table if not exists boss_attempts(id bigserial primary key, character_id uuid not null references characters(id) on delete cascade, boss_id text not null references bosses(id), at timestamptz not null default now(), won boolean not null, rounds int, rewards jsonb);
create index if not exists boss_attempts_char on boss_attempts(character_id, boss_id, at desc);
alter table bosses enable row level security; alter table boss_attempts enable row level security;
drop policy if exists bosses_read on bosses; create policy bosses_read on bosses for select using (true);
drop policy if exists boss_attempts_own on boss_attempts; create policy boss_attempts_own on boss_attempts for select using (character_id in (select id from characters where user_id = auth.uid()));
-- atributos: curva das criaturas (categoria miniboss, vida ×0,55: ~3× a de um monstro comum), ataque e defesa ×0,8; habilidades e recompensas são dados (dá pra criar chefe novo só com um insert)
insert into bosses(id, name, city, x, y, level, hp, atk, def, exp, sprite, tint, abilities, rewards, cooldown_h, retry_min, min_level)
  select b.id, b.name, b.city, b.x, b.y, b.lvl, round((f->>'hp')::int * 0.55), round((f->>'atk')::int * 0.8), round((f->>'def')::int * 0.8), (f->>'exp')::bigint * 6, b.sprite, b.tint, b.ab, b.rew, 6, 10, greatest(1, b.lvl - 15)
  from (values
    ('boss_arken', 'Rei dos Bandidos', 'arken', 55, 1219, 30, 'boss_king', null, '[{"name":"Golpe de Machado","kind":"golpe","every":4,"power":2.2},{"name":"Chamar a Gangue","kind":"invocar","every":8,"power":0.25},{"name":"Fúria do Rei","kind":"furia","below":0.3,"power":1.5}]'::jsonb, '{"gold":3600,"gems":2,"item":"capa","loot_table":"cr_bandido","loot_rolls":4}'::jsonb),
    ('boss_valen', 'Leviatã da Enseada', 'valen', 4580, 1108, 62, 'drowned', 'deep', '[{"name":"Onda Esmagadora","kind":"area","every":5,"power":1.6},{"name":"Abraço das Profundezas","kind":"golpe","every":7,"power":2.6},{"name":"Maré Curativa","kind":"cura","every":9,"power":0.07},{"name":"Fúria Abissal","kind":"furia","below":0.25,"power":1.6}]'::jsonb, '{"gold":7440,"gems":3,"item":"anel_enf","loot_table":"cr_afogado","loot_rolls":4}'::jsonb),
    ('boss_sylvana', 'Ent Ancião Corrompido', 'sylvana', -3025, -1620, 72, 'golem', 'ancient', '[{"name":"Raízes Perfurantes","kind":"golpe","every":4,"power":2.3},{"name":"Esporos Venenosos","kind":"area","every":6,"power":1.4},{"name":"Seiva Antiga","kind":"cura","every":8,"power":0.08},{"name":"Chamar Ents Jovens","kind":"invocar","every":10,"power":0.3}]'::jsonb, '{"gold":8640,"gems":3,"item":"cajado","loot_table":"cr_ent","loot_rolls":4}'::jsonb),
    ('boss_solkar', 'Escorpião-Rei das Dunas', 'solkar', -875, 3439, 82, 'spider', 'sand', '[{"name":"Ferrão Mortal","kind":"golpe","every":3,"power":2.4},{"name":"Tempestade de Areia","kind":"area","every":6,"power":1.7},{"name":"Carapaça Dourada","kind":"escudo","every":9,"power":0.5},{"name":"Fúria do Deserto","kind":"furia","below":0.3,"power":1.7}]'::jsonb, '{"gold":9840,"gems":4,"item":"nucleo","loot_table":"cr_vespa","loot_rolls":4}'::jsonb),
    ('boss_khazad', 'Golem Ancestral da Forja', 'khazad', 2347, -2690, 92, 'golem', 'deep', '[{"name":"Punho de Magma","kind":"golpe","every":4,"power":2.6},{"name":"Erupção","kind":"area","every":7,"power":1.9},{"name":"Núcleo Ardente","kind":"furia","below":0.35,"power":1.6},{"name":"Reforjar","kind":"cura","every":11,"power":0.06}]'::jsonb, '{"gold":11040,"gems":4,"item":"nucleo","loot_table":"cr_golem","loot_rolls":4}'::jsonb),
    ('boss_nocthar', 'Lich da Cidadela', 'nocthar', -2406, -3665, 106, 'fallen', 'void', '[{"name":"Raio Sombrio","kind":"golpe","every":3,"power":2.4},{"name":"Nova Necrótica","kind":"area","every":5,"power":1.8},{"name":"Erguer Mortos","kind":"invocar","every":7,"power":0.35},{"name":"Drenar Vida","kind":"cura","every":8,"power":0.09},{"name":"Forma Final","kind":"furia","below":0.25,"power":1.8}]'::jsonb, '{"gold":12720,"gems":5,"item":"anel_enf","loot_table":"cr_guardiao","loot_rolls":4}'::jsonb),
    ('boss_dragao', 'Ignaroth, o Dragão de Cinzas', 'khazad', 2176, -3102, 120, 'dragon', null, '[{"name":"Mordida","kind":"golpe","every":3,"power":2.5},{"name":"Sopro de Fogo","kind":"area","every":5,"power":2.2},{"name":"Escamas de Basalto","kind":"escudo","every":8,"power":0.6},{"name":"Chamar Dragonetes","kind":"invocar","every":9,"power":0.35},{"name":"Ira do Dragão","kind":"furia","below":0.3,"power":1.9}]'::jsonb, '{"gold":14400,"gems":8,"item":"nucleo","loot_table":"cr_golem","loot_rolls":4}'::jsonb)
  ) b(id, name, city, x, y, lvl, sprite, tint, ab, rew), lateral creature_fit(b.lvl, 'miniboss') f
on conflict (id) do update set name = excluded.name, x = excluded.x, y = excluded.y, hp = excluded.hp, atk = excluded.atk, def = excluded.def, exp = excluded.exp, abilities = excluded.abilities, rewards = excluded.rewards;


-- ---------- viagem rápida: 2 diamantes, cobrado só se a viagem acontecer (tudo numa transação) ----------
create or replace function fast_travel(p_kind text, p_target text) returns jsonb language plpgsql security definer set search_path = public as $$
declare c characters; cost int := coalesce((cfg('travel_fast') ->> 'gems')::int, 2); g bigint; tx int; ty int; h hunts; ci cities; bo bosses; z jsonb; res jsonb;
begin
  select * into c from characters where user_id = auth.uid() for update; if c.id is null then raise exception 'sem personagem'; end if;
  if p_kind = 'hunt' then select * into h from hunts where id = p_target; if h.id is null then raise exception 'área de caça inválida'; end if;
    tx := (h.rect ->> 'x')::int + (h.rect ->> 'w')::int / 2; ty := (h.rect ->> 'y')::int + (h.rect ->> 'h')::int / 2;
  elsif p_kind = 'city' then select * into ci from cities where id = p_target; if ci.id is null then raise exception 'cidade inválida'; end if;
    tx := case when ci.heart then 52 else ci.x end; ty := case when ci.heart then 42 else ci.y + 3 end;
  elsif p_kind = 'boss' then select * into bo from bosses where id = p_target and enabled; if bo.id is null then raise exception 'chefe inválido'; end if; tx := bo.x; ty := bo.y + 8;
  else raise exception 'destino inválido'; end if;
  select gems into g from wallets where character_id = c.id for update;
  if coalesce(g, 0) < cost then raise exception 'a viagem rápida custa % diamantes (você tem %)', cost, coalesce(g, 0); end if;
  perform add_gems(c.id, -cost, 'viagem_rapida', p_kind || ':' || p_target);
  z := zone_at(tx, ty);
  update characters set x = tx, y = ty, pos_at = now(), city_id = z ->> 'city', ring = (z ->> 'ring')::int, pvp_mode = case when (z ->> 'ring')::int = 1 then false else pvp_mode end where id = c.id;
  if p_kind = 'hunt' then res := start_hunt(p_target); else res := get_state(); end if;
  return res || jsonb_build_object('travel', jsonb_build_object('x', tx, 'y', ty, 'cost', cost));
end $$;
grant execute on function fast_travel(text, text) to authenticated;

-- caçada: no continente exige estar na área (o resto da função é igual)
CREATE OR REPLACE FUNCTION public.start_hunt(p_hunt text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c characters; h hunts;
begin
  perform simulate();
  select * into c from characters where user_id = auth.uid() for update; if c.id is null then raise exception 'sem personagem'; end if;
  select * into h from hunts where id = p_hunt; if h.id is null then raise exception 'hunt inválida'; end if;
  -- no continente a caçada começa onde o personagem está: chega andando (grátis) ou pela viagem rápida (diamantes)
  if h.city_id is not null and c.hunt_id is distinct from h.id and (c.pos_at is null or c.pos_at < now() - interval '5 minutes'
     or sqrt(power(c.x - ((h.rect ->> 'x')::int + (h.rect ->> 'w')::int / 2), 2) + power(c.y - ((h.rect ->> 'y')::int + (h.rect ->> 'h')::int / 2), 2)) > (h.rect ->> 'w')::int / 2 + 30) then
    raise exception 'vá até a área de caça (a pé, grátis) ou use a viagem rápida (% diamantes)', coalesce((cfg('travel_fast') ->> 'gems')::int, 2);
  end if;
  perform end_session(c.id, 'troca');
  insert into hunt_sessions(character_id, hunt_id, behavior) values (c.id, h.id, c.behavior);
  insert into hunt_presence(hunt_id, actor_type, actor_id) values (h.id, 'char', c.id::text) on conflict (hunt_id, actor_type, actor_id) do update set last_active_at = now();
  update characters set hunt_id = h.id, task = 'hunt', x = (h.rect->>'x')::int + 1, y = (h.rect->>'y')::int + 1, last_simulated_at = now(), updated_at = now() where id = c.id;
  return get_state();
end $function$;


-- ---------- combate no mapa aberto (servidor decide tudo; respawn por criatura) ----------
create or replace function fight_spawn(p_spawn text) returns jsonb language plpgsql security definer set search_path = public as $$
declare c characters; sp world_spawns; m creatures; st spawn_state; cw jsonb := cfg('open_world'); rm jsonb := cfg('open_world') -> 'rare_mult';
  mhp numeric; matk numeric; atk numeric; def numeric; chp numeric; dps numeric; ttk numeric; taken numeric; heal numeric; npots int := 0; won boolean;
  exp_gain bigint := 0; gold_gain bigint := 0; drops jsonb := '[]'; e drop_entries; qn int; nid uuid; bag_n int; lvl0 int; home cities; dead timestamptz;
begin
  select * into c from characters where user_id = auth.uid() for update; if c.id is null then raise exception 'sem personagem'; end if;
  select * into sp from world_spawns where id = p_spawn; if sp.id is null then raise exception 'criatura inválida'; end if;
  if c.task = 'hunt' then raise exception 'você está numa caçada: saia dela pra lutar no mapa aberto'; end if;
  if c.pos_at is null or c.pos_at < now() - interval '60 seconds' or sqrt(power(c.x - sp.x, 2) + power(c.y - sp.y, 2)) > (cw ->> 'range')::numeric then raise exception 'chegue mais perto da criatura'; end if;
  if c.last_fight_at > now() - make_interval(secs => (cw ->> 'cd_s')::numeric) then raise exception 'devagar'; end if;
  insert into spawn_state(spawn_id) values (sp.id) on conflict do nothing;
  select * into st from spawn_state where spawn_id = sp.id for update;
  if st.dead_until > now() then raise exception 'essa criatura já foi derrotada (volta em % s)', ceil(extract(epoch from st.dead_until - now())); end if;
  select * into m from creatures where id = sp.creature_id;
  mhp := m.hp * (case when sp.rare then (rm ->> 'hp')::numeric else 1 end); matk := m.atk * (case when sp.rare then (rm ->> 'atk')::numeric else 1 end);
  atk := atk_of(c); def := def_of(c); chp := least(c.hp, hp_max(c)); heal := 60 + c.level;
  dps := greatest(1, atk * 0.9 - m.def); ttk := mhp / dps; taken := greatest(0, matk - def) * ttk / 1.2 * (0.85 + random() * 0.3);
  while taken >= chp * 0.7 + npots * heal and npots < c.pots and npots < 5 loop npots := npots + 1; end loop;
  won := taken < chp + npots * heal; lvl0 := c.level;
  if won then
    exp_gain := round(m.exp * (case when sp.rare then (rm ->> 'exp')::numeric else 1 end));
    gold_gain := round((m.gold_min + random() * (m.gold_max - m.gold_min)) * (case when sp.rare then (rm ->> 'gold')::numeric else 1 end));
    c.exp := c.exp + exp_gain; while c.exp >= exp_for(c.level + 1) loop c.level := c.level + 1; end loop;
    if gold_gain > 0 then perform add_gold(c.id, gold_gain, 'mapa_aberto', sp.id); end if;
    for e in select * from drop_entries where table_id = m.loot_table and min_world <= c.world_id loop
      if random() < e.chance * (case when sp.rare then (rm ->> 'drop')::numeric else 1 end) then qn := e.qty_min + floor(random() * (e.qty_max - e.qty_min + 1))::int;
        perform stack_add(c.id, e.template_id, round(e.purity_min + random() * (e.purity_max - e.purity_min))::int, qn); drops := drops || jsonb_build_object('template', e.template_id, 'q', qn); end if;
    end loop;
    if m.drop_item is not null and random() < coalesce(m.drop_chance, 0) * (case when sp.rare then (rm ->> 'drop')::numeric else 1 end) then
      select count(*) into bag_n from inventory where character_id = c.id and container = 'bag';
      if bag_n < 20 then nid := roll_item(m.drop_item, 'mapa:' || sp.id, sp.id || ':' || extract(epoch from now())::text); insert into inventory(item_id, character_id, container, idx) values (nid, c.id, 'bag', bag_n); drops := drops || jsonb_build_object('template', m.drop_item, 'id', nid); end if;
    end if;
    insert into character_kills(character_id, creature_id, kills) values (c.id, m.id, 1) on conflict (character_id, creature_id) do update set kills = character_kills.kills + 1;
    perform quest_kills(c.id, m.id, 1);
    dead := now() + make_interval(secs => case when sp.rare then (cw ->> 'rare_respawn_s')::numeric else (cw ->> 'respawn_min_s')::numeric + random() * ((cw ->> 'respawn_max_s')::numeric - (cw ->> 'respawn_min_s')::numeric) end);
    update spawn_state set dead_until = dead, kills = kills + 1 where spawn_id = sp.id;
    update characters set exp = c.exp, level = c.level, hp = greatest(1, least(hp_max(c), floor(chp + npots * heal - taken))), pots = c.pots - npots, kills = kills + 1, last_fight_at = now(), updated_at = now() where id = c.id;
  else
    -- derrota: volta pra cidade mais perto com metade da vida (sem perder exp nem gold no mapa aberto)
    select * into home from cities order by (case when heart then sqrt(power(greatest(0 - c.x, 0, c.x - 300), 2) + power(greatest(0 - c.y, 0, c.y - 200), 2)) else sqrt(power(c.x - x, 2) + power(c.y - y, 2)) end) limit 1;
    update characters set x = case when home.heart then 52 else home.x end, y = case when home.heart then 42 else home.y + 3 end, pos_at = now(), city_id = home.id, ring = 1, pvp_mode = false,
      hp = greatest(1, floor(hp_max(c) * 0.5)), pots = c.pots - npots, deaths = deaths + 1, last_fight_at = now(), updated_at = now() where id = c.id;
  end if;
  select * into c from characters where id = c.id;
  return jsonb_build_object('won', won, 'exp', exp_gain, 'gold', gold_gain, 'drops', drops, 'pots', npots, 'hp', c.hp, 'hp_max', hp_max(c), 'level', c.level, 'level_up', c.level > lvl0,
    'dead_until', dead, 'x', c.x, 'y', c.y, 'rare', sp.rare, 'creature', m.name, 'rounds', ceil(ttk));
end $$;
-- quem está morto por perto (o cliente desenha só os vivos)
create or replace function spawns_state(p_x int, p_y int) returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'until', st.dead_until)), '[]') from spawn_state st join world_spawns s on s.id = st.spawn_id
  where st.dead_until > now() and s.x between p_x - 400 and p_x + 400 and s.y between p_y - 400 and p_y + 400 $$;
grant execute on function fight_spawn(text), spawns_state(int, int) to authenticated;

-- ---------- chefes: combate por rodadas com habilidades e padrões, resolvido no servidor ----------
create or replace function boss_fight(p_boss text) returns jsonb language plpgsql security definer set search_path = public as $$
declare c characters; b bosses; bc jsonb := cfg('bosses_cfg'); last_win timestamptz; last_loss timestamptz; atk numeric; def numeric; php numeric; pmax numeric; bhp numeric; bmax numeric;
  r int := 0; ab jsonb; dmg numeric; ev text; enraged boolean := false; shield int := 0; adds int := 0; npots int := 0; heal numeric; won boolean := false; log jsonb := '[]'; rew jsonb := '{}';
  e drop_entries; k int; qn int; nid uuid; bag_n int; drops jsonb := '[]'; home cities; mult numeric;
begin
  select * into c from characters where user_id = auth.uid() for update; if c.id is null then raise exception 'sem personagem'; end if;
  select * into b from bosses where id = p_boss and enabled; if b.id is null then raise exception 'chefe inválido'; end if;
  if c.task = 'hunt' then raise exception 'saia da caçada antes de enfrentar o chefe'; end if;
  if c.pos_at is null or c.pos_at < now() - interval '2 minutes' or sqrt(power(c.x - b.x, 2) + power(c.y - b.y, 2)) > (bc ->> 'range')::numeric then raise exception 'vá até o covil do chefe'; end if;
  if c.level < b.min_level then raise exception 'esse chefe exige nível %', b.min_level; end if;
  select max(ba.at) filter (where ba.won), max(ba.at) filter (where not ba.won) into last_win, last_loss from boss_attempts ba where ba.character_id = c.id and ba.boss_id = b.id;
  if last_win > now() - make_interval(hours => b.cooldown_h::int) then raise exception '% volta pra você em % min', b.name, ceil(extract(epoch from last_win + make_interval(hours => b.cooldown_h::int) - now()) / 60); end if;
  if last_loss > now() - make_interval(mins => b.retry_min::int) then raise exception 'recupere-se antes de tentar de novo (% min)', ceil(extract(epoch from last_loss + make_interval(mins => b.retry_min::int) - now()) / 60); end if;
  atk := atk_of(c); def := def_of(c); pmax := hp_max(c); php := least(c.hp, pmax); bmax := b.hp; bhp := bmax; heal := 60 + c.level * 2;
  while r < (bc ->> 'max_rounds')::int loop
    r := r + 1; ev := null;
    -- jogador ataca (crítico 10%); escudo do chefe reduz o dano
    dmg := greatest(1, atk * 0.9 - b.def) * (0.9 + random() * 0.2) * (case when random() < 0.1 then 1.6 else 1 end) * (case when shield > 0 then 0.4 else 1 end);
    bhp := bhp - dmg; if shield > 0 then shield := shield - 1; end if;
    if bhp <= 0 then won := true; log := log || jsonb_build_array(jsonb_build_array(r, round(php), 0, 'O chefe caiu!')); exit; end if;
    -- chefe: ataque normal + habilidades por padrão (a cada N rodadas) e fúria abaixo de X% da vida
    mult := 1;
    for ab in select * from jsonb_array_elements(b.abilities) loop
      if ab ->> 'kind' = 'furia' and not enraged and bhp < bmax * (ab ->> 'below')::numeric then enraged := true; ev := (ab ->> 'name') || ': o chefe entra em fúria!';
      elsif ab ? 'every' and r % (ab ->> 'every')::int = 0 then
        if ab ->> 'kind' = 'golpe' then mult := mult * (ab ->> 'power')::numeric; ev := ab ->> 'name';
        elsif ab ->> 'kind' = 'area' then php := php - b.atk * (ab ->> 'power')::numeric * 0.6 * (0.9 + random() * 0.2); ev := (ab ->> 'name') || ' (ignora defesa)';
        elsif ab ->> 'kind' = 'cura' then bhp := least(bmax, bhp + bmax * (ab ->> 'power')::numeric); ev := (ab ->> 'name') || ': o chefe se cura';
        elsif ab ->> 'kind' = 'escudo' then shield := 3; ev := (ab ->> 'name') || ': dano reduzido por 3 rodadas';
        elsif ab ->> 'kind' = 'invocar' then adds := adds + 1; ev := (ab ->> 'name') || ' (' || adds || ' lacaios)'; end if;
      end if;
    end loop;
    dmg := greatest(1, b.atk * (case when enraged then (select (x ->> 'power')::numeric from jsonb_array_elements(b.abilities) x where x ->> 'kind' = 'furia' limit 1) else 1 end) - def) * mult * (0.85 + random() * 0.3)
      + adds * greatest(1, b.atk - def) * coalesce((select (x ->> 'power')::numeric from jsonb_array_elements(b.abilities) x where x ->> 'kind' = 'invocar' limit 1), 0.25);   -- lacaios: também esbarram na defesa
    php := php - dmg;
    if php < pmax * (bc ->> 'pot_below')::numeric and npots < least(c.pots, (bc ->> 'max_pots')::int) and php > 0 then npots := npots + 1; php := least(pmax, php + heal); ev := coalesce(ev || ' · ', '') || 'você bebe uma poção'; end if;
    log := log || jsonb_build_array(jsonb_build_array(r, greatest(0, round(php)), greatest(0, round(bhp)), ev));
    if php <= 0 then exit; end if;
  end loop;
  if won then
    rew := b.rewards; perform add_gold(c.id, (rew ->> 'gold')::bigint, 'chefe', b.id); if (rew ->> 'gems')::int > 0 then perform add_gems(c.id, (rew ->> 'gems')::int, 'chefe', b.id); end if;
    c.exp := c.exp + b.exp; while c.exp >= exp_for(c.level + 1) loop c.level := c.level + 1; end loop;
    for k in 1..coalesce((rew ->> 'loot_rolls')::int, 1) loop
      for e in select * from drop_entries where table_id = rew ->> 'loot_table' and min_world <= c.world_id loop
        if random() < least(1, e.chance * 4) then qn := e.qty_min + floor(random() * (e.qty_max - e.qty_min + 1))::int; perform stack_add(c.id, e.template_id, round(e.purity_min + random() * (e.purity_max - e.purity_min))::int, qn); drops := drops || jsonb_build_object('template', e.template_id, 'q', qn); end if;
      end loop; end loop;
    select count(*) into bag_n from inventory where character_id = c.id and container = 'bag';
    if rew ? 'item' and bag_n < 20 then nid := roll_item(rew ->> 'item', 'chefe:' || b.id, c.id::text || ':' || extract(epoch from now())::text); insert into inventory(item_id, character_id, container, idx) values (nid, c.id, 'bag', bag_n); drops := drops || jsonb_build_object('template', rew ->> 'item', 'id', nid); end if;
    insert into character_kills(character_id, creature_id, kills) select c.id, b.id, 1 where exists (select 1 from creatures where id = b.id) on conflict (character_id, creature_id) do update set kills = character_kills.kills + 1;
    update characters set exp = c.exp, level = c.level, hp = greatest(1, floor(php)), pots = c.pots - npots, kills = kills + 1, last_fight_at = now(), updated_at = now() where id = c.id;
  else
    select * into home from cities order by (case when heart then sqrt(power(greatest(0 - c.x, 0, c.x - 300), 2) + power(greatest(0 - c.y, 0, c.y - 200), 2)) else sqrt(power(c.x - x, 2) + power(c.y - y, 2)) end) limit 1;
    update characters set x = case when home.heart then 52 else home.x end, y = case when home.heart then 42 else home.y + 3 end, pos_at = now(), city_id = home.id, ring = 1, pvp_mode = false,
      hp = greatest(1, floor(pmax * 0.5)), pots = c.pots - npots, deaths = deaths + 1, last_fight_at = now(), updated_at = now() where id = c.id;
  end if;
  insert into boss_attempts(character_id, boss_id, won, rounds, rewards) values (c.id, b.id, won, r, case when won then rew || jsonb_build_object('drops', drops) else null end);
  if won then insert into chat_messages(channel, character_id, name, body) values ('mundo', null, 'Sistema', format('%s derrotou %s!', c.name, b.name)); end if;
  select * into c from characters where id = c.id;
  return jsonb_build_object('won', won, 'rounds', r, 'log', log, 'boss', jsonb_build_object('id', b.id, 'name', b.name, 'hp', bmax, 'level', b.level), 'hp_max', pmax, 'pots', npots,
    'rewards', case when won then rew || jsonb_build_object('drops', drops, 'exp', b.exp) else null end, 'x', c.x, 'y', c.y, 'level', c.level);
end $$;
create or replace function bosses_view() returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'name', b.name, 'city', b.city, 'x', b.x, 'y', b.y, 'level', b.level, 'hp', b.hp, 'atk', b.atk, 'def', b.def, 'min_level', b.min_level, 'abilities', b.abilities, 'rewards', b.rewards, 'cooldown_h', b.cooldown_h,
    'next', (select max(at) + make_interval(hours => b.cooldown_h::int) from boss_attempts a join characters ch on ch.id = a.character_id where ch.user_id = auth.uid() and a.boss_id = b.id and a.won)) order by b.level), '[]')
  from bosses b where b.enabled $$;
grant execute on function boss_fight(text), bosses_view() to authenticated;


-- ---------- valor de venda numa função só (shop_sell e a cotação usam a mesma conta) ----------
create or replace function shop_sell_value(c characters, p_shop text, p_args jsonb) returns bigint language plpgsql stable security definer set search_path = public as $$
declare sh npc_shops; t item_templates; it items; v bigint; q int; pur int;
begin
  select * into sh from npc_shops where id = p_shop; if sh.id is null or not ('sell' = any(sh.services)) then raise exception 'essa loja não compra'; end if;
  if p_args ? 'item' then
    select i.* into it from items i join inventory v2 on v2.item_id = i.id where i.id = (p_args ->> 'item')::uuid and v2.character_id = c.id and v2.container in ('bag','protected');
    if it.id is null then raise exception 'item não está na mochila'; end if;
    select * into t from item_templates where id = it.template_id;
    if not shop_accepts(p_shop, t) then raise exception '% não compra %', sh.name, t.name; end if;
    v := floor(item_value(it) * price_mult(c.world_id, t) * sh.sell_mult * city_sell_mult(c, t));
  else
    select * into t from item_templates where id = p_args ->> 't'; q := (p_args ->> 'qty')::int; pur := (p_args ->> 'purity')::int;
    if t.id is null or not t.stackable or q is null or q < 1 then raise exception 'material inválido'; end if;
    if not shop_accepts(p_shop, t) then raise exception '% não compra %', sh.name, t.name; end if;
    v := floor(t.sell * q * (0.6 + pur / 100.0 * 0.6) * price_mult(c.world_id, t) * sh.sell_mult * city_sell_mult(c, t) * (1 + least(0.15, prof_level(c.id, 'comercio') * 0.0015)));
  end if;
  return v;
end $$;
create or replace function sell_quote(p_shop text, p_list jsonb) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare c characters; a jsonb; out jsonb := '[]'; v bigint;
begin
  select * into c from characters where user_id = auth.uid(); if c.id is null then raise exception 'sem personagem'; end if;
  for a in select * from jsonb_array_elements(p_list) loop
    begin v := shop_sell_value(c, p_shop, a); out := out || jsonb_build_array(a || jsonb_build_object('gold', v));
    exception when others then out := out || jsonb_build_array(a || jsonb_build_object('error', sqlerrm)); end;
  end loop;
  return jsonb_build_object('quotes', out, 'budget', npc_budget_left(c.id));
end $$;
grant execute on function sell_quote(text, jsonb) to authenticated;

-- shop_sell passa a usar shop_sell_value (mesmo comportamento)
CREATE OR REPLACE FUNCTION public.shop_sell(p_shop text, p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c characters; sh npc_shops; t item_templates; it items; v bigint; left_ bigint; q int; pur int;
begin
  select * into c from characters where user_id = auth.uid() for update; if c.id is null then raise exception 'sem personagem'; end if;
  v := shop_sell_value(c, p_shop, p_args);
  if p_args ? 'item' then select i.* into it from items i where i.id = (p_args ->> 'item')::uuid; select * into t from item_templates where id = it.template_id;
  else select * into t from item_templates where id = p_args ->> 't'; q := (p_args ->> 'qty')::int; pur := (p_args ->> 'purity')::int; end if;
  left_ := npc_budget_left(c.id); if v > left_ then raise exception 'o caixa da loja só tem % gold agora (renova a cada % h)', left_, cfg('npc_budget') ->> 'regen_h'; end if;
  if it.id is not null then delete from inventory where item_id = it.id; delete from items where id = it.id; else perform stack_take(c.id, t.id, pur, q); end if;
  perform add_gold(c.id, v, 'venda_loja_' || p_shop, t.id); perform npc_budget_use(c.id, v); perform prof_gain(c.id, 'comercio', greatest(1, v / 50));
  return jsonb_build_object('gold', v, 'state', get_state());
end $function$;

